package com.glassbox.chess; import com.glassbox.chess.domain.*; import com.glassbox.chess.util.AsciiBoardPrinter; import org.junit.jupiter.api.Test; import static org.junit.jupiter.api.Assertions.*; public class BoardTest{@Test void initialPositionHasCorrectPieces(){Board b=new Board();b.setupInitialPosition();String s=AsciiBoardPrinter.print(b);assertTrue(s.contains("r n b q k b n r"));assertTrue(s.contains("R N B Q K B N R"));assertEquals(PieceType.KING,b.getPieceAt(new Position(4,0)).getType());assertEquals(32,count(b));}private int count(Board b){int n=0;for(int f=0;f<8;f++)for(int r=0;r<8;r++)if(b.getPieceAt(new Position(f,r))!=null)n++;return n;}@Test void positionConvertsAlgebraic()throws Exception{assertEquals("e4",Position.fromAlgebraic("e4").toAlgebraic());}}
